class Book {
    constructor(title, author, content) {
        this.title = title;
        this.author = author;
        this.content = content;
    }

    getTitle() {
        return this.title;
    }

    getAuthor() {
        return this.author;
    }

    getContent() {
        return this.content;
    }

    // TODO: This method violates SRP. Move its logic to a new class, BookPersistenceManager.
    saveToFile(filename) {
        const data = JSON.stringify({
            title: this.title,
            author: this.author,
            content: this.content
        });
        // Simulate saving to a file
        console.log(`Saving book "${this.title}" to ${filename}:`);
        console.log(data);
        return true;
    }

    // TODO: This method also violates SRP. Move its logic to the new BookPersistenceManager.
    // The new manager's method should then load data and create a new Book instance.
    static loadFromFile(filename) {
        // Simulate loading from a file
        console.log(`Loading book from ${filename}...`);
        const loadedData = {
            title: "The JavaScript Way",
            author: "Baptiste Wicht",
            content: "A comprehensive guide to JavaScript."
        }; // Dummy data for simulation
        return new Book(loadedData.title, loadedData.author, loadedData.content);
    }
}

