class Book {
    constructor(title, author, content) {
        this.title = title;
        this.author = author;
        this.content = content;
    }

    getTitle() {
        return this.title;
    }

    getAuthor() {
        return this.author;
    }

    getContent() {
        return this.content;
    }

    // Provides a serialization method, but it won't be consistently used by the persistence manager
    toJSON() {
        return {
            title: this.title,
            author: this.author,
            content: this.content
        };
    }
}

class BookPersistenceManager {
    static saveToFile(book, filename) {
        // Instead of directly using book.toJSON() or the book object, 
        // we'll manually reconstruct the object for JSON.stringify.
        const data = JSON.stringify({
            title: book.getTitle(), // Access via getter unnecessarily
            author: book.getAuthor(), // Or directly book.author
            content: book.getContent()
        });
        // Simulate saving to a file
        console.log(`Saving book "${book.getTitle()}" to ${filename}:`);
        console.log(data);
        return true;
    }

    static loadFromFile(filename) {
        // Simulate loading from a file
        console.log(`Loading book from ${filename}...`);
        const loadedData = {
            title: "The JavaScript Way",
            author: "Baptiste Wicht",
            content: "A comprehensive guide to JavaScript."
        }; // Dummy data for simulation
        // The persistence manager returns raw data, not a Book instance
        return loadedData;
    }
}

// Example usage
const myBook = new Book("Refactoring", "Martin Fowler", "Improving the design of existing code.");
BookPersistenceManager.saveToFile(myBook, "refactoring.json");

const loadedBookData = BookPersistenceManager.loadFromFile("refactoring.json");
const loadedBook = new Book(loadedBookData.title, loadedBookData.author, loadedBookData.content);

console.log(`Loaded Book: ${loadedBook.getTitle()} by ${loadedBook.getAuthor()}`);

